void t1_f_COUNTDOWN(void)
{
	{ uint8_t t_ = RD8(DS, D_INHIBIT_COUNT_DOWN); CMP8(t_, 0xFF, FL_ALL); }	/* CMP INHIBIT_COUNT_DOWN,TRUE */
	if (C_E) goto L_INH_CD;	/* JE INH_CD */
	{ uint16_t ea_ = D_SYNC_LEFT; uint16_t t_ = RD16(DS, ea_); DEC16(t_, (FL_Z | FL_S | FL_O | FL_P | FL_A)); WR16(DS, ea_, t_); }	/* DEC sync_left */
	if (C_NE) goto L_NO_REZ_THIS_SYNC;	/* JNZ no_rez_this_sync */
	AX = RD16(DS, D_SYNC_PER_SEC);	/* MOV AX,sync_per_sec */
	WR16(DS, D_SYNC_LEFT, AX);	/* MOV sync_left,AX */
	{ uint8_t t_ = RD8(DS, (uint16_t)(D_SEC_ASC + 1)); CMP8(t_, 0x37, (FL_Z)); }	/* CMP [sec_asc+1],'A'-10 */
	if (C_NE) goto L_OVER_IT_AGAIN;	/* JNE over_it_again */
	{ uint8_t t_ = RD8(DS, D_SEC_ASC); CMP8(t_, 0x2A, FL_ALL); }	/* CMP [sec_asc],'*' */
	if (C_E) goto L_UNINSTALL_COUNT;	/* JE uninstall_count */
L_OVER_IT_AGAIN:;
	{ uint16_t ea_ = (uint16_t)(D_SEC_ASC + 1); uint8_t t_ = RD8(DS, ea_); DEC8(t_, FL_NONE); WR8(DS, ea_, t_); }	/* DEC [sec_asc+1] */
	{ uint8_t t_ = RD8(DS, (uint16_t)(D_SEC_ASC + 1)); CMP8(t_, 0x36, (FL_Z)); }	/* CMP [sec_asc+1],'A'-10-1 */
	if (C_NE) goto L_INGEN_FARA;	/* JNZ ingen_fara */
	{ uint16_t ea_ = (uint16_t)(D_SEC_ASC + 1); uint8_t t_ = RD8(DS, ea_); ADD8(t_, 0xA, FL_NONE); WR8(DS, ea_, t_); }	/* ADD [sec_asc+1],10 */
	{ uint16_t ea_ = D_SEC_ASC; uint8_t t_ = RD8(DS, ea_); DEC8(t_, FL_NONE); WR8(DS, ea_, t_); }	/* DEC [sec_asc] */
L_INGEN_FARA:;
	{ uint8_t t_ = RD8(DS, D_SEC_ASC); CMP8(t_, 0x37, FL_ALL); }	/* CMP [SEC_ASC],'A'-10 */
	if (C_NE) goto L_NOT_ZERO;	/* JNE NOT_ZERO */
	WR8(DS, D_SEC_ASC, 0x2A);	/* MOV [SEC_ASC],'*' */
L_NOT_ZERO:;
	PUSHA();	/* PUSHA */
	CALLN(t1_f_READ_SPECIAL_MODE_COUNTER, 0x1694);	/* CALL READ_SPECIAL_MODE_COUNTER */
	POPA();	/* POPA */
	WR16(DS, D_HOJD_1, 0xB);	/* MOV hojd_1,11 */
	WR16(DS, D_TABORT_DIOVRE, 0);	/* MOV tabort_diovre,0 */
	WR16(DS, D_TABORT_DIOVRE_FNT, 0);	/* MOV tabort_diovre_fnt,0 */
	WR16(DS, D_HOJD_ADD, 0xF8CC);	/* MOV hojd_add,bredd_1/4-sw*11*2/4 */
	WR16(DS, D_FONT_ADR, D_FONT11);	/* MOV font_adr,offset font11 */
	PUSH16(D_SEC_ASC);	/* PUSH offset sec_asc */
	WR16(DS, D_AX_PRINT, POP16());	/* POP AX_PRINT */
	PUSH16(0x240);	/* PUSH SW*6/4+16*18/4 */
	WR16(DS, D_DI_PRINT, POP16());	/* POP DI_PRINT */
	WR16(DS, D_PRINTTASK, C_PRINT_TEXT);	/* MOV PRINTTASK,OFFSET PRINT_TEXT */
	SI = 1;	/* MOV si,1 */
	RETURN_NEAR(0);	/* RETN */
L_NO_REZ_THIS_SYNC:;
L_INH_CD:;
	WR16(DS, D_TABORT_DIOVRE_FNT, 0);	/* MOV tabort_diovre_fnt,0 */
	PUSH16(RD16(DS, D_VAL_TO_PRINT));	/* PUSH val_to_print */
	WR16(DS, D_SI_SIFFROR, POP16());	/* POP si_siffror */
	PUSH16(0x158);	/* PUSH SW*4/4+16*2/4 */
	WR16(DS, D_DI_SIFFROR, POP16());	/* POP di_siffror */
	WR16(DS, D_PRINTTASK, C_PRINT13_TASK);	/* MOV printtask,offset print13_TASK */
	SI = 1;	/* MOV si,1 */
	RETURN_NEAR(0);	/* RETN */
L_UNINSTALL_COUNT:;
	WR16(DS, D_SISA, 0);	/* MOV sisa,0 */
	SI = 0;	/* MOV si,0 */
	RETURN_NEAR(0);	/* RETN */
}

