void t1_f_READPAL(void)
{
	DX = 0x3C7;	/* MOV DX,3C7H */
	AL = 0;	/* MOV AL,0 */
	OUT8(DX, AL);	/* OUT DX,AL */
	DX = 0x3C9;	/* MOV DX,3C9H */
	CX = 0x300;	/* MOV CX,3*256 */
	AX = CS;	/* MOV AX,CS */
	ES = AX;	/* MOV ES,AX */
	DI = D_PALLE;	/* MOV DI,OFFSET CS:PALLE */
L_RPAL:;
	AL = IN8(DX);	/* IN AL,DX */
	x_stosb();	/* STOSB */
	CX = (uint16_t)(CX - 1);	/* LOOP RPAL */
	if (CX != 0) { X_POLL(); goto L_RPAL; }
	RETURN_NEAR(0);	/* RETN */
}

void t1_f_SETPAL(void)
{
	DX = 0x3C8;	/* MOV DX,3C8H */
	AL = 0;	/* MOV AL,0 */
	OUT8(DX, AL);	/* OUT DX,AL */
	CX = 0x300;	/* MOV CX,3*256 */
	DI = D_PALLE;	/* MOV DI,OFFSET CS:PALLE */
L_SPAL:;
	AL = RD8(CS, (uint16_t)(DI));	/* MOV AL,CS:[DI] */
	XOR8(AH, AH, FL_NONE);	/* XOR AH,AH */
	MUL16(BX);	/* MUL BX */
	AL = AH;	/* MOV AL,AH */
	DX = 0x3C9;	/* MOV DX,3C9H */
	OUT8(DX, AL);	/* OUT DX,AL */
	INC16(DI, (FL_Z | FL_S | FL_O | FL_P | FL_A));	/* INC DI */
	CX = (uint16_t)(CX - 1);	/* LOOP SPAL */
	if (CX != 0) { X_POLL(); goto L_SPAL; }
	RETURN_NEAR(0);	/* RETN */
}

