	{ uint16_t t_ = RD16(DS, D_TILTCOUNTER); CMP16(t_, 0, FL_ALL); }	/* CMP TILTCOUNTER,0 */
	if (C_E) goto L_NOTI;	/* JZ NOTI */
	{ uint16_t ea_ = D_TILTCOUNTER; uint16_t t_ = RD16(DS, ea_); DEC16(t_, (FL_Z | FL_S | FL_O | FL_P | FL_A)); WR16(DS, ea_, t_); }	/* DEC TILTCOUNTER */
