	if (C_B) { X_POLL(); goto L_NASTAAREA; }	/* JB NASTAAREA */
	x_lodsw(DS);	/* LODSW */
	CMP16(CX, AX, (FL_C | FL_Z));	/* CMP CX,AX */
	if (C_A) { X_POLL(); goto L_NASTAAREA; }	/* JA NASTAAREA */
	x_lodsw(DS);	/* LODSW */
	CMP16(DX, AX, (FL_C | FL_Z));	/* CMP DX,AX */
	if (C_A) { X_POLL(); goto L_NASTAAREA; }	/* JA NASTAAREA */
	x_lodsw(DS);	/* LODSW */
	{ uint16_t t_ = RD16(DS, D_LASTCHECK); CMP16(t_, AX, FL_ALL); }	/* CMP LASTCHECK,AX */
	if (C_E) goto L_CALLREADY;	/* JE CALLREADY */
