void t1_f_SPRINGUP(void)
{
	CL = RD8(DS, D_SPRINGPOS);	/* MOV Cl,springpos */
	XOR8(CH, CH, FL_ALL);	/* XOR Ch,Ch */
	if (CX == 0) goto L_NOUP;	/* JCXZ NOUP */
	{ uint8_t t_ = RD8(DS, D_SPRING_VALID); CMP8(t_, 0, (FL_Z)); }	/* CMP SPRING_VALID,FALSE */
	if (C_E) goto L_DOUP2;	/* JE DOUP2 */
	{ uint8_t t_ = RD8(DS, D_HI_RES); CMP8(t_, 0xFF, (FL_Z)); }	/* CMP hi_res,true */
	if (C_E) goto L_NILSBEDRUPP;	/* JE nilsbedrupp */
	AX = 0xFF76;	/* MOV ax,(-5000/15)/2*TT/NN */
	goto L_KUKENKARL;	/* JMP kukenkarl */
L_NILSBEDRUPP:;
	AX = 0xFF5A;	/* MOV ax,(-5000/15)/2 */
L_KUKENKARL:;
	IMUL16(CX);	/* IMUL Cx */
	BP = AX;	/* MOV bp,ax */
	AX = RD16(DS, D_SLUMP_COUNTERN);	/* MOV ax,slump_countern */
	AND16(AX, 0xFF, FL_NONE);	/* AND ax,255 */
	SUB16(BP, AX, FL_NONE);	/* SUB bp,ax */
	{ uint8_t t_ = RD8(DS, D_MAKE_BAD); CMP8(t_, 0xFF, (FL_Z)); }	/* CMP MAKE_BAD,TRUE */
	if (C_E) goto L_BADDAREN;	/* JE BADDAREN */
	WR16(DS, D_Y_HAST, BP);	/* MOV Y_HAST,bp */
	WR16(DS, D_X_HAST, 0);	/* MOV X_HAST,0 */
	WR16(DS, D_ROTATION, 0);	/* MOV ROTATION,0 */
L_BADDAREN:;
	AX = RD16(DS, D_SLUMP_COUNTERN);	/* MOV AX,slump_countern */
	WR16(DS, D_ROTATION, AX);	/* MOV rotation,AX */
	{ uint16_t ea_ = D_ROTATION; uint16_t t_ = RD16(DS, ea_); AND16(t_, 0xF, FL_NONE); WR16(DS, ea_, t_); }	/* AND rotation,15 */
L_DOUP2:;
	AL = RD8(DS, D_SPRINGPOS);	/* MOV AL,SPRINGPOS */
	XOR8(AH, AH, FL_NONE);	/* XOR AH,AH */
	SHL16(AX, 6, (FL_C));	/* SHL AX,6 */
	BL = 0x20;	/* MOV BL,(SPRINGH-1)*2 */
	DIV8(BL);	/* DIV BL */
	BH = AL;	/* MOV bh,AL */
	CL = RD8(DS, D_SFJADER);	/* MOV CL,sfjader+0 */
	BL = RD8(DS, (uint16_t)(D_SFJADER + 1));	/* MOV BL,sfjader+1 */
	DL = RD8(DS, (uint16_t)(D_SFJADER + 3));	/* MOV DL,sfjader+3 */
	INC8(DL, (FL_Z | FL_S | FL_O | FL_P | FL_A));	/* INC DL */
	AL = 0x11;	/* MOV AL,17 */
	x_int(0x66);	/* INT 66H */
	WR8(DS, D_SPRINGPOS, 0);	/* MOV springpos,0 */
	CALLN(t1_f_PUTSPRING, 0x2054);	/* CALL putspring */
	{ uint8_t t_ = RD8(DS, D_MOUSEINSTALLED); CMP8(t_, 0xFF, FL_ALL); }	/* CMP MOUSEINSTALLED,TRUE */
	if (C_NE) goto L_NO_M_INST;	/* JNE NO_M_INST */
	AX = 4;	/* MOV AX,04H */
	XOR16(CX, CX, FL_ALL);	/* XOR CX,CX */
	DX = 1;	/* MOV DX,MOUSEMIDDLE */
	x_int(0x33);	/* INT 33H */
L_NO_M_INST:;
L_NOUP:;
	WR16(DS, D_SPRINGTASK, C_SPRINGSTEEN);	/* MOV SPRINGTASK,OFFSET SPRINGSTEEN */
	RETURN_NEAR(0);	/* RETN */
}

