L_NOTHIRES12:;
	AH = RD8(DS, D_SPLITLINE);	/* MOV ah,BYTE PTR SPLITLINE */
	DEC8(AH, FL_NONE);	/* DEC AH */
	OUT16(DX, AX);	/* OUT dx,ax */
	AL = RD8(DS, (uint16_t)(D_SPLITLINE + 1));	/* MOV al,BYTE PTR SPLITLINE+1 */
	AND8(AL, 1, FL_NONE);	/* AND al,1 */
	SHL8(AL, 4, FL_NONE);	/* SHL al,4 */
	AH = AL;	/* MOV ah,al */
	AL = 7;	/* MOV al,07 */
	OUT8(DX, AL);	/* OUT dx,al */
	INC16(DX, FL_NONE);	/* INC dx */
	AL = IN8(DX);	/* IN al,dx */
	DEC16(DX, FL_NONE);	/* DEC dx */
	AND8(AL, 0xEF, FL_NONE);	/* AND al,11101111b */
	OR8(AL, AH, FL_NONE);	/* OR al,ah */
	AH = AL;	/* MOV ah,al */
	AL = 7;	/* MOV al,7 */
	OUT16(DX, AX);	/* OUT dx,ax */
	DX = 0x3D4;	/* MOV dx,3d4h */
	AL = 9;	/* MOV al,09 */
	OUT8(DX, AL);	/* OUT dx,al */
	INC16(DX, FL_NONE);	/* INC dx */
	AL = IN8(DX);	/* IN al,dx */
	DEC16(DX, FL_NONE);	/* DEC dx */
	AND8(AL, 0xBF, FL_ALL);	/* AND al,10111111b */
	AH = AL;	/* MOV ah,al */
	AL = 9;	/* MOV al,09 */
	OUT16(DX, AX);	/* OUT dx,ax */
	RETURN_NEAR(0);	/* RET */
